import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sum_of_divisors(n):
    return sum(get_divisors(n))

def count_divisors(n):
    return len(get_divisors(n))

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

candidates = []
for m in range(2, 101):
    sigma_m = sum_of_divisors(m)
    if is_square(sigma_m):
        tau_m = count_divisors(m)
        candidates.append({
            'm': m,
            'sigma(m)': sigma_m,
            'tau(m)': tau_m,
            'divisors': get_divisors(m)
        })

print("Candidates m <= 100 such that sigma(m) is a square:")
for cand in candidates:
    print(f"m={cand['m']}, sigma(m)={cand['sigma(m)']}, tau(m)={cand['tau(m)']}")

small_tau_candidates = [
    cand for cand in candidates if cand['tau(m)'] <= 5
]

print("\nCandidates with tau(m) <= 5:")
for cand in small_tau_candidates:
    print(f"m={cand['m']}, divisors={cand['divisors']}")
